  "name" TEXT
  "group_id" INTEGER -- REFERENCES "product_groups"("id")
);

physical SQLite table: "monthly_sales"
CREATE TABLE "monthly_sales" (
  "product_id" INTEGER -- PRIMARY KEY; REFERENCES "products"("id")
  "mth" TEXT -- PRIMARY KEY
  "qty" INTEGER
);

